from PySide6.QtGui import QIcon, QPixmap, QPainter
from PySide6.QtCore import Qt, QSize
from PySide6.QtSvg import QSvgRenderer


def _svg_to_pixmap(svg_str: str, size: int = 24, color: str = "#999") -> QPixmap:
    """Convert an SVG string to a QPixmap with color tint."""
    colored = svg_str.replace("currentColor", color)
    renderer = QSvgRenderer(colored.encode("utf-8"))
    pm = QPixmap(QSize(size, size))
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(p)
    p.end()
    return pm


def icon(name: str, size: int = 24, color: str = "#999", active: str = "#ddd") -> QIcon:
    """Create a multi-state icon (normal + active/checked)."""
    ico = QIcon()
    ico.addPixmap(_svg_to_pixmap(_SVG[name], size, color))
    ico.addPixmap(_svg_to_pixmap(_SVG[name], size, active), QIcon.Mode.Active)
    ico.addPixmap(_svg_to_pixmap(_SVG[name], size, active), QIcon.Mode.Selected)
    return ico


